SELECT *, NTILE(4) OVER (ORDER BY balance ASC, id ASC) AS balance_bucket, AVG(balance) OVER (PARTITION BY account_type ORDER BY opened_date ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS balance_avg_6, RANK() OVER (PARTITION BY customer_id ORDER BY balance ASC NULLS FIRST) AS balance_rank, AVG(balance) OVER (PARTITION BY account_type ORDER BY opened_date ASC, id ASC ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS balance_avg_5_prior, SUM(balance) OVER (PARTITION BY account_type ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_balance FROM accounts;
